// ============================================================================
// HSI_apb: APB4 register wrapper around HSI_top (generated by
// scripts/apb/gen_apb.py from scripts/apb/specs/HSI.json; do not edit)
// ----------------------------------------------------------------------------
//  - APB4 slave, zero wait states (PREADY = PSEL & PENABLE), 32-bit data,
//    12-bit byte address; PSLVERR on an unmapped or misaligned access.
//  - PSTRB byte lanes apply to every writable register.
//  - The core runs on PCLK/PRESETN; protocol pins pass through unchanged.
//  - Register map: docs/ip/HSI.md
// ============================================================================
module HSI_apb (
  input  logic        PCLK,
  input  logic        PRESETN,
  input  logic        PSEL,
  input  logic        PENABLE,
  input  logic        PWRITE,
  input  logic [11:0] PADDR,
  input  logic [31:0] PWDATA,
  input  logic [3:0]  PSTRB,
  output logic [31:0] PRDATA,
  output logic        PREADY,
  output logic        PSLVERR,
  output logic        irq,
  output logic tx_data,
  output logic tx_flag,
  input logic tx_ready_in,
  output logic tx_wake,
  input logic rx_data,
  input logic rx_flag,
  output logic rx_ready_out,
  input logic rx_wake
);
  localparam logic [31:0] ID_VALUE = 32'h48530200;

  // ---------------- core ----------------
  logic [7:0]    c_cfg_div;
  logic [2:0]    c_cfg_chbits;
  logic          c_cfg_rx_en;
  logic          c_cfg_wake;
  logic          c_txq_valid;
  logic          c_txq_ready;
  logic [3:0]    c_txq_ch;
  logic [31:0]   c_txq_data;
  logic          c_tx_brk;
  logic          c_tx_busy;
  logic          c_tx_done;
  logic          c_rxq_valid;
  logic          c_rxq_ready;
  logic [3:0]    c_rxq_ch;
  logic [31:0]   c_rxq_data;
  logic          c_rx_break;
  logic          c_err_overflow;
  logic          c_err_stray;
  logic          c_err_ds;
  logic          c_err_timeout;
  HSI_top u_core (
    .clk(PCLK),
    .rst_n(PRESETN),
    .tx_data(tx_data),
    .tx_flag(tx_flag),
    .tx_ready_in(tx_ready_in),
    .tx_wake(tx_wake),
    .rx_data(rx_data),
    .rx_flag(rx_flag),
    .rx_ready_out(rx_ready_out),
    .rx_wake(rx_wake),
    .cfg_div(c_cfg_div),
    .cfg_chbits(c_cfg_chbits),
    .cfg_rx_en(c_cfg_rx_en),
    .cfg_wake(c_cfg_wake),
    .txq_valid(c_txq_valid),
    .txq_ready(c_txq_ready),
    .txq_ch(c_txq_ch),
    .txq_data(c_txq_data),
    .tx_brk(c_tx_brk),
    .tx_busy(c_tx_busy),
    .tx_done(c_tx_done),
    .rxq_valid(c_rxq_valid),
    .rxq_ready(c_rxq_ready),
    .rxq_ch(c_rxq_ch),
    .rxq_data(c_rxq_data),
    .rx_break(c_rx_break),
    .err_overflow(c_err_overflow),
    .err_stray(c_err_stray),
    .err_ds(c_err_ds),
    .err_timeout(c_err_timeout)
  );

  // ---------------- APB decode ----------------
  wire        acc     = PSEL & PENABLE;
  wire        wr      = acc & PWRITE;
  wire        rd      = acc & ~PWRITE;
  wire [31:0] wmask   = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [11:0] hit;
  always_comb begin
    hit = '0;
    if (PADDR[1:0] == 2'b00 && PADDR[11:2] < 10'd12) hit[PADDR[11:2]] = 1'b1;
  end
  assign PREADY  = acc;
  assign PSLVERR = acc & ~|hit;

  // ---------------- registers ----------------
  logic [8:0] irq_status, irq_enable, irq_set;
  logic [31:0] scratch;
  logic [12:0] r_CFG;   // 12'h014 CFG
  logic [3:0] h_TX0;   // 12'h018 TX0 holding register
  logic [31:0] h_TX1;   // 12'h01C TX1 holding register
  logic [3:0] h_RX0;   // 12'h020 RX0 holding register
  logic [31:0] h_RX1;   // 12'h024 RX1 holding register
  logic [0:0] p_CMD;   // 12'h028 CMD (pulses)
  logic full_TX;
  logic avail_RX;

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      irq_status <= '0; irq_enable <= '0; scratch <= '0;
      r_CFG <= 13'hC07;
      h_TX0 <= '0;
      h_TX1 <= '0;
      h_RX0 <= '0;
      h_RX1 <= '0;
      p_CMD <= '0;
      full_TX <= 1'b0;
      avail_RX <= 1'b0;
    end else begin
      irq_status <= (irq_status & ~((wr && hit[1]) ? PWDATA[8:0] & wmask[8:0] : '0)) | irq_set;
      if (wr && hit[2]) irq_enable <= (irq_enable & ~wmask[8:0]) | (PWDATA[8:0] & wmask[8:0]);
      if (wr && hit[4]) scratch <= (scratch & ~wmask) | (PWDATA & wmask);
      if (wr && hit[5]) r_CFG <= (r_CFG & ~wmask[12:0]) | (PWDATA[12:0] & wmask[12:0]);
      p_CMD <= (wr && hit[10]) ? PWDATA[0:0] & wmask[0:0] : '0;
      if (wr && hit[6] && !full_TX) h_TX0 <= (h_TX0 & ~wmask[3:0]) | (PWDATA[3:0] & wmask[3:0]);
      if (wr && hit[7] && !full_TX) h_TX1 <= (h_TX1 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[7] && !full_TX) full_TX <= 1'b1;
      else if (full_TX && c_txq_ready) full_TX <= 1'b0;
      if (c_rxq_valid && (!avail_RX || (rd && hit[9]))) begin
        h_RX0[3:0] <= c_rxq_ch[3:0];
        h_RX1[31:0] <= c_rxq_data[31:0];
        avail_RX <= 1'b1;
      end else if (rd && hit[9]) avail_RX <= 1'b0;
    end
  end

  // ---------------- core inputs ----------------
  assign c_cfg_div = r_CFG[7:0];
  assign c_cfg_chbits = r_CFG[10:8];
  assign c_cfg_rx_en = r_CFG[11:11];
  assign c_cfg_wake = r_CFG[12:12];
  assign c_txq_ch[3:0] = h_TX0[3:0];
  assign c_txq_data[31:0] = h_TX1[31:0];
  assign c_tx_brk = p_CMD;
  assign c_txq_valid = full_TX;
  assign c_rxq_ready = ~avail_RX | (rd & hit[9]);

  // ---------------- interrupts and flags ----------------
  always_comb begin
    irq_set = '0;
    irq_set[0] = c_tx_done;
    irq_set[1] = c_rx_break;
    irq_set[2] = c_err_overflow;
    irq_set[3] = c_err_stray;
    irq_set[4] = c_err_ds;
    irq_set[5] = c_err_timeout;
    irq_set[6] = full_TX & c_txq_ready;
    irq_set[7] = wr & (hit[6] | hit[7]) & full_TX;
    irq_set[8] = c_rxq_valid & (~avail_RX | (rd & hit[9]));
  end
  assign irq = |(irq_status & irq_enable);
  wire [1:0] flags = {avail_RX, full_TX};

  // ---------------- read mux ----------------
  logic [31:0] rdata;
  always_comb begin
    rdata = '0;
    case (PADDR[11:2])
      10'd0: rdata = ID_VALUE;
      10'd1: rdata = 32'(irq_status);
      10'd2: rdata = 32'(irq_enable);
      10'd3: rdata = 32'(flags);
      10'd4: rdata = scratch;
      10'd5: rdata = 32'(r_CFG);
      10'd6: rdata = 32'(h_TX0);
      10'd7: rdata = 32'(h_TX1);
      10'd8: rdata = 32'(h_RX0);
      10'd9: rdata = 32'(h_RX1);
      10'd11: rdata = 32'({c_tx_busy});
      default: rdata = '0;
    endcase
  end
  assign PRDATA = (rd && |hit) ? rdata : '0;
endmodule
